RANGE_END = 100          # Upper bound for most explorations
COLUMN_COUNT = 8         # Width of the prime ladder columns
BLOCK_WIDTH = 80         # Nice terminal width for wrapping

# Theme constants – animal, color, and a few "fun" numbers
THEME_ANIMAL = "Luna the Lobster"
