# ----------------------------------------------------------------------
# 2. UTILITY FUNCTIONS (pure, no blocking calls)
# ----------------------------------------------------------------------
def clear_screen():
    """Clear terminal cleanly using escape sequences."""
    print('\033[2J\033[H', end='')

def centered(text, width):
    """Center text inside a fixed width, padding spaces on left/right."""
    lines = text.splitlines()
    return ' '.join(
        ' ' * ((width - len(line)) // 2) + line
        for line in lines
    )

def fmt_block(title, subtitle, body, width=BLOCK_WIDTH):
    """Print a nicely wrapped block."""
    print(centered(title, width))
    if subtitle:
        print(centered(subtitle, width))
    print(centered(body, width))
    print()

# ----------------------------------------------------------------------
# 3. NUMBER THEORY BUILDINGS
# ----------------------------------------------------------------------
def is_prime(n):
    """Classic primality test, O(√n)."""
    if n < 2:
        return False
    if n in (2,3):
        return True
    if n % 2 == 0:
        return False
    limit = int(n**0.5)
    for d in range(3, limit+1, 2):
        if n % d == 0:
            return False
    return True

def proper_divisors_sum(n):
    """Sum of proper divisors of n (i.e. all divisors except n)."""
    if n < 2:
        return 0
    total = 1  # 1 always divides any n > 1
    limit = int(n**0.5)
    for d in range(2, limit+1):
        if n % d == 0:
            total += d
            other = n // d
            if other != d and other != n:
                total += other
    return total

def is_perfect(n):
    """True if n equals sum of proper divisors."""
    return proper_divisors_sum(n) == n

def is_abundant(n):
    """True if n is strictly less than sum of proper divisors."""
    return proper_divisors_sum(n) > n

def primes_up_to(limit):
    """List of all primes ≤ limit."""
    primes = [2]
    for n in range(3, limit+1, 2):
        if is_prime(n):
            primes.append(n)
    return primes

def palindromic_primes_in_range(low, high):
    """Return primes between low and high that are also palindromes."""
    return [n for n in range(low, high+1) if is_prime(n) and str(n) == str(n)[::-1]]

def fibonacci_primes(limit):
    """First few Fibonacci numbers that are prime."""
    fib = [0, 1]
    while fib[-1] < limit:
        fib.append(fib[-1] + fib[-2])
    return [n for n in fib if is_prime(n) and n > 1]

def prime_gap_stats(low, high):
    """Smallest and largest gap between successive primes in the range."""
    primes = primes_up_to(high)
    primes = [p for p in primes if low <= p <= high]
    if len(primes) < 2:
        return None, None
    gaps = [primes[i+1] - primes[i] for i in range(len(primes)-1)]
    return min(gaps), max(gaps)

