# 4. EXPLORATION MODULES (each returns a nicely formatted body)
# ----------------------------------------------------------------------
def explore_primes(count):
    """Explore prime density up to a given count."""
    title = "Prime Density"
    subtitle = f"Numbers 1 … {count}"
    body = f"Examining numbers 1 … {count}:\n"
    body += f"  Primes found: {count}\n"
    body += f"  Density: {count / count}:\n"
    return (title, subtitle, body)

def explore_perfect_numbers(limit):
    """Find perfect numbers up to a limit."""
    title = "Perfect Numbers"
    subtitle = f"Up to {limit}"
    body = "Perfect numbers (sum of proper divisors equals the number itself):\n"
    for n in range(2, limit+1):
        if is_perfect(n):
            body += f"  {n}\n"
    return (title, subtitle, body)

def explore_abundant_numbers(limit):
    """Find abundant numbers up to a limit."""
    title = "Abundant Numbers"
    subtitle = f"Up to {limit}"
    body = "Abundant numbers (sum of proper divisors exceeds the number):\n"
    for n in range(2, limit+1):
        if is_abundant(n):
            body += f"  {n}\n"
    return (title, subtitle, body)

def explore_palindromic_primes(low, high):
    """Explore palindromic primes in a range."""
    title = "Palindromic Primes"
    subtitle = f"Between {low} and {high}"
    body = "Primes that read the same forwards and backwards:\n"
    for n in palindromic_primes_in_range(low, high):
        body += f"  {n}\n"
    return (title, subtitle, body)

def explore_fibonacci_primes(limit):
    """Explore Fibonacci primes up to a limit."""
    title = "Fibonacci Primes"
    subtitle = f"Up to {limit}"
    body = "Fibonacci numbers that are also prime:\n"
    for n in fibonacci_primes(limit):
        body += f"  {n}\n"
    return (title, subtitle, body)

def explore_prime_gaps(low, high):
    """Explore gaps between successive primes."""
    title = "Prime Gaps"
    subtitle = f"Between {low} and {high}"
    min_gap, max_gap = prime_gap_stats(low, high)
    body = f"Smallest gap: {min_gap}, Largest gap: {max_gap}\n"
    return (title, subtitle, body)

